# Let's try to build a graph iteratively
# Start with no edges, add edges one by one, ensuring no short cycles

import random
from collections import deque

def has_short_cycle(adj, n, max_cycle=5):
    """Check if there's a cycle of length <= max_cycle"""
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u] and dist[v] >= dist[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_cycle:
                        return True, cycle_len, (s, u, v)
    return False, None, None

def check_degrees(deg, min_d=3, max_d=6):
    """Check if all degrees are within bounds"""
    return all(min_d <= d <= max_d for d in deg)

def try_random_build(n=15, min_deg=3, max_deg=6, max_attempts=10000):
    for attempt in range(max_attempts):
        adj = [[] for _ in range(n)]
        deg = [0]*n

        # List of all possible edges
        all_edges = [(i,j) for i in range(n) for j in range(i+1, n)]
        random.shuffle(all_edges)

        # Try to add edges greedily
        for u,v in all_edges:
            # Check if adding this edge would create a short cycle
            # Temporarily add edge
            adj[u].append(v)
            adj[v].append(u)
            deg[u] += 1
            deg[v] += 1

            has_cycle, cycle_len, _ = has_short_cycle(adj, n, 5)

            if has_cycle:
                # Remove edge
                adj[u].pop()
                adj[v].pop()
                deg[u] -= 1
                deg[v] -= 1
            elif deg[u] > max_deg or deg[v] > max_deg:
                # Remove edge
                adj[u].pop()
                adj[v].pop()
                deg[u] -= 1
                deg[v] -= 1

        # Check if all vertices have degree >= min_deg
        if all(d >= min_deg for d in deg):
            # Verify girth
            has_cycle, cycle_len, _ = has_short_cycle(adj, n, 5)
            if not has_cycle:
                # Also verify no longer cycles... actually we only checked up to 5
                # Let's find the actual girth
                min_cycle = float('inf')
                for s in range(n):
                    dist = [-1]*n
                    parent = [-1]*n
                    dist[s] = 0
                    q = deque([s])
                    while q:
                        u = q.popleft()
                        for v in adj[u]:
                            if dist[v] == -1:
                                dist[v] = dist[u] + 1
                                parent[v] = u
                                q.append(v)
                            elif v != parent[u] and dist[v] >= dist[u]:
                                cycle_len = dist[u] + dist[v] + 1
                                if cycle_len < min_cycle:
                                    min_cycle = cycle_len

                if min_cycle >= 6:
                    return adj, deg, min_cycle

        if attempt % 1000 == 0:
            print(f"Attempt {attempt}...")

    return None, None, None

result = try_random_build(15, 3, 6, 5000)
